import { describe, it, expect } from "vitest";
import { SKILLS } from "@/lib/generated/skills-data";
import { CATEGORY_COLORS } from "@/lib/category-colors";
import { AGENTS } from "@/lib/generated/shared-data";
import {
  AGENT_CATEGORY_TO_SKILL,
  categorizeSkill,
  TAG_CATEGORY_MAP,
} from "@/lib/skill-category";

// Real generated data on purpose: the bug this guards was a rule that looked
// fine on hand-written fixtures and mislabelled real skills.
const cat = (slug: string) => categorizeSkill(SKILLS[slug]);

describe("categorizeSkill on the real skill set", () => {
  it.each([
    // The five the 2026-09-25 site QA caught, each a substring hit.
    ["business-case", "product"], // "ui" inside "build-vs-buy"
    ["testing-unit", "testing"], // "vite" inside "vitest-4"
    ["security-patterns", "security"], // "llm" inside "llm-safety"
    ["product-analytics", "product"], // "test" inside "ab-test", before Product
    ["remember", "development"], // "ci" inside "decisions"
    // Same class, found by the full sweep.
    ["distributed-systems", "backend"], // "ui" inside "circuit-breaker"
    ["write-prd", "product"], // "ui" inside "requirements"
    ["interaction-patterns", "frontend"], // "rag" inside "drag-drop"
    ["cover", "testing"], // "ai" inside "testcontainers"
    ["dream", "development"], // "ai" inside "maintenance"
    ["dev", "development"], // agent-browser is not research
  ])("%s is %s", (slug, expected) => {
    expect(cat(slug)).toBe(expected);
  });

  it("gives every skill a category the card can color", () => {
    const known = new Set(Object.keys(CATEGORY_COLORS));
    for (const [slug, skill] of Object.entries(SKILLS)) {
      expect(known.has(categorizeSkill(skill)), slug).toBe(true);
    }
  });
});

describe("categorizeSkill rule", () => {
  const noAgents = {};

  it("matches whole tags and whole tokens, never substrings", () => {
    expect(categorizeSkill({ tags: ["build-vs-buy"], agent: null }, noAgents)).toBe(
      "development",
    );
    expect(categorizeSkill({ tags: ["decisions"], agent: null }, noAgents)).toBe(
      "development",
    );
    expect(categorizeSkill({ tags: ["react-aria"], agent: null }, noAgents)).toBe(
      "frontend",
    );
    expect(categorizeSkill({ tags: ["next.js"], agent: null }, noAgents)).toBe(
      "frontend",
    );
  });

  it("lets the owning agent outweigh one stray tag", () => {
    const agents = { "product-strategist": "product" };
    expect(
      categorizeSkill({ tags: ["ab-test", "cohort"], agent: "product-strategist" }, agents),
    ).toBe("product");
  });

  it("lets a clear tag majority beat the owning agent", () => {
    const agents = { "data-pipeline-engineer": "data" };
    expect(
      categorizeSkill(
        { tags: ["rag", "llm", "embeddings"], agent: "data-pipeline-engineer" },
        agents,
      ),
    ).toBe("ai");
  });

  it("only produces categories the card can color", () => {
    const known = new Set(Object.keys(CATEGORY_COLORS));
    for (const key of Object.keys(TAG_CATEGORY_MAP)) expect(known.has(key), key).toBe(true);
    for (const v of Object.values(AGENT_CATEGORY_TO_SKILL)) expect(known.has(v), v).toBe(true);
  });

  it("maps every real agent category, so no owner is silently ignored", () => {
    for (const a of AGENTS) {
      expect(AGENT_CATEGORY_TO_SKILL[a.category], `${a.name}: ${a.category}`).toBeDefined();
    }
  });
});
